class Selector {
    static String select(int n) {
        var result = switch (n) {
            case 1, 2 -> "L" + n;
            case 3 -> {
                var t = n * 2;
                yield "M" + t;
            }
            case 4, 5 -> "H" + (n - 1);
            default -> "X";
        };
        return result;
    }
}
public class Main {
    public static void main(String[] args) {
        var x = 1;
        System.out.print(Selector.select(x));
    }
}

