public class Main {
    public static void main(String[] args) {
        outer:
        for (int i = 0; i < 3; i++) {
            switch (i) {
                case 0:
                    System.out.print("A");
                case 1:
                    System.out.print("B");
                    break;
                case 2:
                    System.out.print("C");
                    continue outer;
                default:
                    System.out.print("D");
                    break outer;
            }
            System.out.print("|");
        }
        System.out.print("E");
    }
}

